581	  uint32_t element_count = keys.size();
582	  uint32_t inout_size = std::max(Align(element_count * sizeof(uint32_t), 16), 16u);
583	  bool detailed_profiling = DetailedProfilingEnabled();
584	
585	  Reallocate(&staging_, inout_size,
586	             VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT, true);
587	  Reallocate(&keys_, inout_size,
588	             VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT |
589	                 VK_BUFFER_USAGE_TRANSFER_DST_BIT);
590	
591	  VrdxSorterStorageRequirements requirements;
592	  vrdxGetSorterStorageRequirements(sorter_, element_count, &requirements);
593	  Reallocate(&storage_, requirements.size, requirements.usage);
594	
595	  std::memcpy(staging_.map, keys.data(), element_count * sizeof(uint32_t));
596	  vmaFlushAllocation(allocator_, staging_.allocation, 0, inout_size);
597	
598	  VkCommandBufferBeginInfo command_buffer_begin_info = {
599	      VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
600	  command_buffer_begin_info.flags = VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT;
601	  vkBeginCommandBuffer(command_buffer_, &command_buffer_begin_info);
602	
603	  vkCmdResetQueryPool(command_buffer_, query_pool_, 0, timestamp_count);
604	
605	  VkBufferCopy region = {};
606	  region.srcOffset = 0;
607	  region.dstOffset = 0;
608	  region.size = element_count * sizeof(uint32_t);
609	  if (region.size != 0) vkCmdCopyBuffer(command_buffer_, staging_.buffer, keys_.buffer, 1, &region);
610	
611	  vkEndCommandBuffer(command_buffer_);
612	
613	  VkSubmitInfo submit = {VK_STRUCTURE_TYPE_SUBMIT_INFO};
614	  submit.commandBufferCount = 1;
615	  submit.pCommandBuffers = &command_buffer_;
616	  vkQueueSubmit(queue_, 1, &submit, fence_);
617	  WaitForFence(device_, fence_, "key upload");
618	  vkResetFences(device_, 1, &fence_);
619	
620	  vkBeginCommandBuffer(command_buffer_, &command_buffer_begin_info);
621	
622	  VkMemoryBarrier sort_before = {VK_STRUCTURE_TYPE_MEMORY_BARRIER};
623	  sort_before.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
624	  sort_before.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
625	  vkCmdPipelineBarrier(command_buffer_, VK_PIPELINE_STAGE_TRANSFER_BIT,
626	                       VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &sort_before, 0, NULL, 0,
627	                       NULL);
628	
629	  if (!detailed_profiling) {
630	    vkCmdWriteTimestamp(command_buffer_, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, query_pool_, 0);
631	  }
632	  vrdxCmdSort(command_buffer_, sorter_, element_count, keys_.buffer, 0, storage_.buffer, 0,
633	              detailed_profiling ? query_pool_ : VK_NULL_HANDLE, 0);
634	  if (!detailed_profiling) {
635	    vkCmdWriteTimestamp(command_buffer_, VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, query_pool_, 1);
636	  }
637	
638	  vkEndCommandBuffer(command_buffer_);
639	  auto cpu_start = std::chrono::steady_clock::now();
640	  vkQueueSubmit(queue_, 1, &submit, fence_);
