644	
645	  vkBeginCommandBuffer(command_buffer_, &command_buffer_begin_info);
646	
647	  VkMemoryBarrier sort_after = {VK_STRUCTURE_TYPE_MEMORY_BARRIER};
648	  sort_after.srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT;
649	  sort_after.dstAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
650	  vkCmdPipelineBarrier(command_buffer_, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
651	                       VK_PIPELINE_STAGE_TRANSFER_BIT, 0, 1, &sort_after, 0, NULL, 0, NULL);
652	
653	  region.srcOffset = 0;
654	  region.dstOffset = 0;
655	  region.size = element_count * sizeof(uint32_t);
656	  if (region.size != 0) vkCmdCopyBuffer(command_buffer_, keys_.buffer, staging_.buffer, 1, &region);
657	
