#include "MultiRadixSort.h"
#include "engine/core/GPUContext.h"
#include "engine/util/Paths.h"
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <numeric>
#include <vector>

// Match vulkan_radix_sort benchmark settings
constexpr int kWarmupRuns = 5;
constexpr int kTimedRuns  = 10;

double median(std::vector<double>& v) {
    std::sort(v.begin(), v.end());
    if (v.size() % 2 == 1) return v[v.size() / 2];
    return (v[v.size() / 2 - 1] + v[v.size() / 2]) / 2.0;
}

int main(int argc, char** argv) {
#ifdef RESOURCE_DIRECTORY_PATH
    engine::Paths::m_resourceDirectoryPath = RESOURCE_DIRECTORY_PATH;
#endif

    // Parse NUM_BLOCKS from VKR_BLOCKS env var (default 24, optimal compromise)
    uint32_t numBlocks = 24;
    const char* envBlocks = std::getenv("VKR_BLOCKS");
    if (envBlocks) {
        numBlocks = static_cast<uint32_t>(std::strtoul(envBlocks, nullptr, 10));
        if (numBlocks == 0) numBlocks = 32;
    }

    // parse sizes from argv
    std::vector<uint32_t> sizes;
    if (argc >= 2) {
        for (int i = 1; i < argc; i++) {
            sizes.push_back(static_cast<uint32_t>(std::strtoul(argv[i], nullptr, 10)));
        }
    } else {
        sizes = {1024, 2048, 4096, 8192, 16384, 32768, 65536, 131072, 262144, 524288, 1048576};
    }

    engine::GPUContext gpu(engine::Queues::QueueFamilies::COMPUTE_FAMILY | engine::Queues::TRANSFER_FAMILY);

    try {
        gpu.init();

        auto app = std::make_shared<engine::MultiRadixSort>();
        app->init(&gpu);

        // Print CSV header with blocks info
        std::cout << "# VKR_BLOCKS=" << numBlocks << std::endl;
        std::cout << "n,gpu_median_ms,gpu_min_ms,gpu_max_ms" << std::endl;

        for (uint32_t n : sizes) {
            if (n == 0) continue;
            try {
                // Warmup runs (discard timing)
                for (int i = 0; i < kWarmupRuns; ++i) {
                    app->execute(n, numBlocks);
                }

                // Timed runs
                std::vector<double> gpu_times;
                gpu_times.reserve(kTimedRuns);
                for (int i = 0; i < kTimedRuns; ++i) {
                    double ms = app->execute(n, numBlocks);
                    gpu_times.push_back(ms);
                }

                double med = median(gpu_times);
                double mn = *std::min_element(gpu_times.begin(), gpu_times.end());
                double mx = *std::max_element(gpu_times.begin(), gpu_times.end());

                std::cout << n << "," << med << "," << mn << "," << mx << std::endl;
            } catch (const std::exception &e) {
                std::cerr << "N=" << n << " failed: " << e.what() << std::endl;
            }
        }

        app->cleanup();
        gpu.shutdown();
    } catch (const std::exception &e) {
        std::cerr << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

