double MultiRadixSort::execute(uint32_t numElements, uint32_t numBlocksPerWorkgroup) {
    if (!m_initialized) {
        throw std::runtime_error("MultiRadixSort::init() must be called before execute()");
    }
    m_numElements = numElements;

    const uint32_t NUM_BLOCKS_PER_WORKGROUP = numBlocksPerWorkgroup;
    uint32_t globalInvocationSize = m_numElements / NUM_BLOCKS_PER_WORKGROUP;
    uint32_t remainder = m_numElements % NUM_BLOCKS_PER_WORKGROUP;
    globalInvocationSize += remainder > 0 ? 1 : 0;
    m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, globalInvocationSize, 1, 1);
    m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT, globalInvocationSize, 1, 1);

    // push constants
    const uint32_t NUM_WORKGROUPS = m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width;
    assert(NUM_WORKGROUPS == m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT).width);
    m_pass->m_pushConstantsHistogram.g_num_elements = m_numElements;
    m_pass->m_pushConstantsHistogram.g_num_workgroups = NUM_WORKGROUPS;
    m_pass->m_pushConstantsHistogram.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;
    m_pass->m_pushConstants.g_num_elements = m_numElements;
    m_pass->m_pushConstants.g_num_workgroups = NUM_WORKGROUPS;
    m_pass->m_pushConstants.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;

    // buffers
    prepareBuffers();
    std::cout << PRINT_PREFIX << "Sorting " << m_numElements << " " << (sizeof(m_elementsIn[0]) * 8) << "bit numbers." << std::endl;

    // set storage buffers
    uint32_t activeIndex = m_gpuContext->getActiveIndex();

    // m_buffer0
    m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[0].get()); // iteration 0 and 2 (0,0)
    m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[0].get());            // iteration 0 and 2 (1,0)
    m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[0].get());  // iteration 1 and 3 (1,1)

    m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[1].get()); // iteration 1 and 3 (0,0)
    m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[1].get());                      // iteration 0 and 2 (1,1)
    m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[1].get());            // iteration 1 and 3 (1,0)

    m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 1, m_buffers[2].get());
    m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT, 2, m_buffers[2].get());

    // execute pass — single command buffer, single submit (fair: matches VRDX's 1× submit)
    if (m_gpuContext->m_timestampPeriod <= 0.0f || m_gpuContext->m_computeTimestampValidBits == 0) {
        throw std::runtime_error("Compute queue does not support valid timestamp queries!");
    }

    VkQueryPoolCreateInfo queryPoolInfo{};
    queryPoolInfo.sType = VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO;
    queryPoolInfo.queryType = VK_QUERY_TYPE_TIMESTAMP;
    queryPoolInfo.queryCount = 2;  // just start + end

    struct QueryPoolGuard {
        VkDevice device = VK_NULL_HANDLE;
        VkQueryPool pool = VK_NULL_HANDLE;
        ~QueryPoolGuard() {
            if (pool != VK_NULL_HANDLE) vkDestroyQueryPool(device, pool, nullptr);
        }
    } timestampQueries{m_gpuContext->m_device};

    if (vkCreateQueryPool(m_gpuContext->m_device, &queryPoolInfo, nullptr, &timestampQueries.pool) != VK_SUCCESS) {
        throw std::runtime_error("Failed to create timestamp query pool!");
    }
    vkResetQueryPool(m_gpuContext->m_device, timestampQueries.pool, 0, 2);

    // Enable setup overhead (fill+update+barrier) for first iteration
    m_pass->m_doSetupOverhead = true;

    // Single submit: all 4 iterations in one command buffer, no semaphores
    std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
    m_pass->executeSingleSubmit(timestampQueries.pool, 0, 1);
    vkQueueWaitIdle(m_gpuContext->m_queues->getQueue(Queues::COMPUTE));
    std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
    double gpuSortTime = (static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count()) * std::pow(10, -3));

    // Read timestamps
    uint64_t timestamps[2];
    if (vkGetQueryPoolResults(m_gpuContext->m_device, timestampQueries.pool, 0, 2, sizeof(timestamps), timestamps, sizeof(uint64_t), VK_QUERY_RESULT_64_BIT | VK_QUERY_RESULT_WAIT_BIT) != VK_SUCCESS) {
        throw std::runtime_error("Failed to read timestamp query results!");
    }

    const uint64_t timestampMask = m_gpuContext->m_computeTimestampValidBits == 64 ? ~0ull : ((1ull << m_gpuContext->m_computeTimestampValidBits) - 1ull);
    auto applyMask = [&](uint64_t ts) { return ts & timestampMask; };
    const uint64_t ts0 = applyMask(timestamps[0]);
    const uint64_t ts1 = applyMask(timestamps[1]);
    const uint64_t delta = ts1 >= ts0 ? ts1 - ts0 : timestampMask - ts0 + ts1 + 1;
    const double gpuTimestampEnvelopeMs = static_cast<double>(delta) * m_gpuContext->m_timestampPeriod / 1000000.0;

    std::cout << PRINT_PREFIX << "GPU sort finished in " << gpuSortTime << "[ms]." << std::endl;
    std::cout << PRINT_PREFIX << "GPU timestamp envelope (single submit): " << gpuTimestampEnvelopeMs << "[ms]." << std::endl;
    std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_ENVELOPE_MS " << gpuTimestampEnvelopeMs << std::endl;

    // cpu sorting
    double cpuSortTime = sort(m_elementsIn);
    std::cout << PRINT_PREFIX << "CPU sort finished in " << cpuSortTime << "[ms]." << std::endl;

    // verify result
    verify(m_elementsIn);

    // release buffers for this size (pass is reused)
    releaseBuffers();

    return gpuTimestampEnvelopeMs;
}

void MultiRadixSort::cleanup() {
    if (m_initialized && m_pass) {
        m_pass->release();
        m_initialized = false;
        std::cout << PRINT_PREFIX << "Pipeline released." << std::endl;
    }
}

void MultiRadixSort::prepareBuffers() {
    m_elementsIn.clear();
    generateRandomNumbers(m_elementsIn, m_numElements);
    //        printBuffer("elements_in", m_elementsIn, m_numElements);
    auto settings0 = Buffer::BufferSettings{.m_sizeBytes = getNumElementsBytes(), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.elementBuffer0"};
    m_buffers[0] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings0, m_elementsIn.data());

    std::vector<SORT_TYPE> zeros;
    generateZeros(zeros, m_numElements);
    auto settings1 = Buffer::BufferSettings{.m_sizeBytes = getNumElementsBytes(), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.elementBuffer1"};
    m_buffers[1] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings1, zeros.data());
    auto settings2 = Buffer::BufferSettings{.m_sizeBytes = static_cast<uint32_t>(m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width * RADIX_SORT_BINS * sizeof(uint32_t)), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.histogramsBuffer"};
    m_buffers[2] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings2, zeros.data());
}

void MultiRadixSort::verify(std::vector<SORT_TYPE> &reference) {
    std::vector<SORT_TYPE> data(m_numElements);
    m_buffers[0]->downloadWithStagingBuffer(data.data());
    //            printBuffer("elements_out", data, m_numElements);
    testSort(reference, data);
}

