            VkExtent3D scatterWG = getWorkGroupCount(RADIX_SORT);
            vkCmdDispatch(commandBuffer, scatterWG.width, scatterWG.height, scatterWG.depth);

            // Barrier between iterations (scatter writes → next histogram reads)
            if (i < NUM_ITERATIONS - 1) {
